import { AnimatePresence, motion, MotionConfig } from "motion/react";
import { useCallback, useMemo, useState, type JSX } from "react";
type keys =
  | "EuroBill"
  | "WelcomeCard"
  | "AmericanDollar"
  | "CanadianDollar"
  | "TODOListPaper"
  | "CreditCard";

const Wallet = () => {
  const [stuffInWallet, setStuffInWallet] = useState<keys[]>([]);

  const toggleAddToWallet = useCallback((i: keys) => {
    setStuffInWallet((prev) =>
      prev.includes(i) ? prev.filter((elem) => elem !== i) : [...prev, i],
    );
  }, []);

  const OutWalletRenderMap: Record<keys, JSX.Element> = useMemo(() => {
    return {
      AmericanDollar: (
        <motion.button
          key="out-AmericanDollar"
          layoutId="AmericanDollar"
          className="left-2 absolute top-4 cursor-pointer "
          animate={{ rotate: -4, scale: 1 }}
          whileTap={{ scale: 0.95 }}
          exit={{ opacity: 0 }}
          onClick={() => {
            toggleAddToWallet("AmericanDollar");
          }}
        >
          <AmericanDollar width={280} />
        </motion.button>
      ),
      EuroBill: (
        <motion.button
          key="out-EuroBill"
          layoutId="EuroBill"
          className="right-12 absolute top-5 cursor-pointer z-22"
          onClick={() => {
            toggleAddToWallet("EuroBill");
          }}
          animate={{ rotate: 0 }}
          whileTap={{ scale: 0.95 }}
          exit={{ opacity: 0 }}
        >
          <EuroBill width={230} />
        </motion.button>
      ),

      CanadianDollar: (
        <motion.button
          key="out-CanadianDollar"
          layoutId="CanadianDollar"
          onClick={() => {
            toggleAddToWallet("CanadianDollar");
          }}
          className=" cursor-pointer absolute top-4 left-1/2 -translate-x-1/2 z-20  "
          animate={{ rotate: 2, scale: 1 }}
          whileTap={{ scale: 0.95 }}
          exit={{ opacity: 0 }}
        >
          <CanadianDollar width={320} />
        </motion.button>
      ),

      CreditCard: (
        <motion.button
          key="out-CreditCard"
          layoutId="CreditCard"
          className="absolute top-50 left-1/2 -translate-x-1/2 z-20 cursor-pointer"
          animate={{ rotate: 0, scale: 1 }}
          whileTap={{ scale: 0.95 }}
          exit={{ opacity: 0 }}
          onClick={() => {
            toggleAddToWallet("CreditCard");
          }}
        >
          <CreditCard width={220} />
        </motion.button>
      ),
      TODOListPaper: (
        <motion.button
          key="out-TODOListPaper"
          layoutId="TODOListPaper"
          className="absolute top-46 left-16 z-5 cursor-pointer"
          animate={{ rotate: -12, scale: 1 }}
          whileTap={{ scale: 0.95 }}
          exit={{ opacity: 0 }}
          onClick={() => {
            toggleAddToWallet("TODOListPaper");
          }}
        >
          <TODOListPaper width={250} />
        </motion.button>
      ),
      WelcomeCard: (
        <motion.button
          key="out-WelcomeCard"
          layoutId="WelcomeCard"
          className="absolute top-40  rotate-0 right-32 z-10 cursor-pointer"
          animate={{ rotate: 10, scale: 1 }}
          whileTap={{ scale: 0.95 }}
          exit={{ opacity: 0 }}
          onClick={() => {
            toggleAddToWallet("WelcomeCard");
          }}
        >
          <WelcomeCard width={120} />
        </motion.button>
      ),
    };
  }, [toggleAddToWallet]);

  const [allToggle, setAllToggle] = useState<boolean>(false);

  return (
    <MotionConfig transition={{ type: "spring", duration: 0.5, bounce: 0.2 }}>
      <div className=" absolute top-20 w-5xl left-1/2 -translate-x-1/2 ">
        <AnimatePresence mode="popLayout">
          {stuffInWallet.map((e) => {
            return OutWalletRenderMap[e];
          })}
        </AnimatePresence>
      </div>
      <AnimatePresence initial={false} mode="popLayout">
        <motion.div
          initial={{ y: 200, scale: 0.9 }}
          transition={{
            y: !allToggle ? { delay: 0.15 } : {},
          }}
          animate={stuffInWallet.length === 0 ? { y: 0, scale: 1.2 } : {}}
          className="relative bg-transparent p-2 size-72 active:transition-transform active:scale-95"
        >
          {/* top pocket */}
          <div className="rounded-t-[42px] absolute top-0 left-0 w-72 h-25 bg-linear-to-b from-[#1E1E1E] to-[#101010] rounded-b-[35%] z-10 bg-[url('https://img.magnific.com/free-photo/original-black-leather-texture-background_24972-1600.jpg')] bg-cover bg-center  brightness-75 contrast-110 shadow-[0px_2px_4px_0px_#000] overflow-hidden">
            {/* Stichting */}
            <div className="pointer-events-none absolute top-2 left-2  h-18 w-68 rounded-t-[42px] border-t-2 border-r-2 border-l-2 border-dashed border-[#2A2822] bg-transparent z-1 brightness-200" />
            <AnimatePresence mode="popLayout">
              {!stuffInWallet.includes("EuroBill") && (
                <motion.button
                  key="in-EuroBill"
                  layoutId="EuroBill"
                  className="left-24 absolute top-18 cursor-pointer z-22 scale-90 overflow-hidden"
                  onClick={() => {
                    toggleAddToWallet("EuroBill");
                  }}
                  animate={{ rotate: -1 }}
                  whileTap={{ scale: 0.95 }}
                  exit={{ opacity: 0 }}
                >
                  <EuroBill width={200} />
                </motion.button>
              )}
            </AnimatePresence>
            <AnimatePresence mode="popLayout">
              {!stuffInWallet.includes("AmericanDollar") && (
                <motion.button
                  key="in-AmericanDollar"
                  layoutId="AmericanDollar"
                  className="left-8 absolute top-4 cursor-pointer z-2 max-w-56 overflow-hidden"
                  animate={{ rotate: -2, scale: 1 }}
                  whileTap={{ scale: 0.95 }}
                  exit={{ opacity: 0 }}
                  onClick={() => {
                    toggleAddToWallet("AmericanDollar");
                  }}
                >
                  <AmericanDollar width={300} />
                </motion.button>
              )}
            </AnimatePresence>
            <AnimatePresence mode="popLayout">
              {!stuffInWallet.includes("CanadianDollar") && (
                <motion.button
                  key="in-CanadianDollar"
                  layoutId="CanadianDollar"
                  animate={{ rotate: 5, scale: 1 }}
                  whileTap={{ scale: 0.95 }}
                  exit={{ opacity: 0 }}
                  onClick={() => {
                    toggleAddToWallet("CanadianDollar");
                  }}
                  className="cursor-pointer absolute top-10 left-2 z-20 max-w-66 overflow-hidden"
                >
                  <CanadianDollar width={400} />
                </motion.button>
              )}
            </AnimatePresence>
          </div>
          <AnimatePresence mode="popLayout">
            {!stuffInWallet.includes("WelcomeCard") && (
              <motion.button
                key="in-WelcomeCard"
                layoutId="WelcomeCard"
                animate={{ rotate: 0, scale: 1 }}
                whileTap={{ scale: 0.95 }}
                exit={{ opacity: 0 }}
                className="absolute top-24 left-42 z-10 cursor-pointer"
                onClick={() => {
                  toggleAddToWallet("WelcomeCard");
                }}
              >
                <WelcomeCard width={70} />
              </motion.button>
            )}
          </AnimatePresence>

          <AnimatePresence mode="popLayout">
            {!stuffInWallet.includes("TODOListPaper") && (
              <motion.button
                key="in-TODOListPaper"
                layoutId="TODOListPaper"
                className="absolute top-28 left-4 z-10 cursor-pointer"
                animate={{ rotate: 5, scale: 1 }}
                whileTap={{ scale: 0.95 }}
                exit={{ opacity: 0 }}
                onClick={() => {
                  toggleAddToWallet("TODOListPaper");
                }}
              >
                <TODOListPaper width={140} />
              </motion.button>
            )}
          </AnimatePresence>

          <AnimatePresence mode="popLayout">
            {!stuffInWallet.includes("CreditCard") && (
              <motion.button
                key="in-CreditCard"
                layoutId="CreditCard"
                animate={{ rotate: -5, scale: 1 }}
                whileTap={{ scale: 0.95 }}
                exit={{ opacity: 0 }}
                className="absolute top-36 left-16 z-10 cursor-pointer"
                onClick={() => {
                  toggleAddToWallet("CreditCard");
                }}
              >
                <CreditCard width={120} />
              </motion.button>
            )}
          </AnimatePresence>

          {/* middle pocket */}
          <div className="pointer-events-none rounded-b-[35%] z-10 absolute top-42 left-0 w-72 h-20 bg-linear-to-b from-[#1E1E1E] to-[#101010] bg-[url('https://img.magnific.com/free-photo/original-black-leather-texture-background_24972-1600.jpg')] bg-cover bg-center brightness-75 contrast-105" />

          <div className="rounded-b-[35%] z-4 overflow-hidden absolute top-16 left-0 w-72 h-26  bg-linear-to-b from-[#1E1E1E] to-[#101010] bg-[url('https://img.magnific.com/free-photo/original-black-leather-texture-background_24972-1600.jpg')] bg-cover bg-center brightness-75 contrast-105 shadow-[0px_2px_4px_0px_#000]">
            {/* Stichting */}
            <div className="pointer-events-none absolute -top-6 left-0 z-4 h-20 w-72 rounded-b-[40%] border-b-2 border-dashed border-[#908577] bg-transparent" />
          </div>

          {/* bottom pocket */}

          <button
            onClick={() => {
              if (stuffInWallet.length === 6) {
                setStuffInWallet([]);
                setAllToggle(false);
              } else {
                setStuffInWallet([
                  "AmericanDollar",
                  "CanadianDollar",
                  "CreditCard",
                  "EuroBill",
                  "TODOListPaper",
                  "WelcomeCard",
                ]);
                setAllToggle(true);
              }
            }}
            className="cursor-pointer absolute top-32 left-0 w-72 h-40  bg-linear-to-b from-[#1E1E1E] to-[#101010] rounded-b-[52px] bg-[url('https://img.magnific.com/free-photo/original-black-leather-texture-background_24972-1600.jpg')] bg-cover bg-center brightness-[0.65] contrast-100"
          />

          <div
            style={{ perspective: 300 }}
            className="absolute top-39 right-5 z-12"
          >
            <motion.div
              style={{ transformOrigin: "top center" }}
              whileHover={{ rotateX: 20 }}
              transition={{
                type: "spring",
                stiffness: 180,
                damping: 8,
                mass: 2,
              }}
            >
              <Receipt width={90} />
            </motion.div>
          </div>

          {/* Stichting */}
          <div className="pointer-events-none absolute top-24 left-0 z-10 h-22 w-72 rounded-b-[40%] border-b-2 border-dashed border-[#908577] bg-transparent" />
        </motion.div>
      </AnimatePresence>
    </MotionConfig>
  );
};

export default Wallet;

